#include "automation_runner.h"
namespace billiardgl { int runAutomation(AutomationTransport&t,AutomationController&c,const std::string&mode,const std::function<bool(const std::string&)>&screenshot){if(!t.writeMessage(json::stringify(automationReadyEvent(mode,"stdio",c.capabilities()))))return 2;while(true){TransportReadResult in=t.readMessage();if(in.eof)return 0;if(!in.ok){t.writeMessage(json::stringify(automationProtocolError("transport_error",in.error)));continue;}json::ParseResult p=json::parse(in.message);if(!p.ok){t.writeMessage(json::stringify(automationProtocolError("parse_error",p.error)));continue;}AutomationRequestResult q=parseAutomationRequest(p.value);if(!q.ok){int id=0;try{if(p.value.has("id"))id=p.value.at("id").asInt();}catch(...){}t.writeMessage(json::stringify(automationErrorResponse(id,q.errorCode,q.errorMessage)));continue;}ControllerResult r=c.handle(q.request);if(r.screenshotRequested&&(!screenshot||!screenshot(r.screenshotPath)))r.response=automationErrorResponse(q.request.id,"screenshot_failed","failed to save framebuffer");if(!t.writeMessage(json::stringify(r.response)))return 2;if(r.quitRequested)return 0;}} }
